WITH scored AS (SELECT *, DENSE_RANK() OVER (PARTITION BY product_id ORDER BY quantity NULLS LAST) quantity_dense_rank, ROUND(quantity / SUM(quantity) OVER (PARTITION BY order_id), 4) quantity_share, SUM(unit_price) OVER w_running running_unit_price, ROUND(quantity / SUM(quantity) OVER (PARTITION BY order_id), 4) quantity_share_2, ROUND(quantity / SUM(quantity) OVER (PARTITION BY product_id, order_id), 4) quantity_share_3 FROM order_items WINDOW w_running AS (PARTITION BY product_id ORDER BY unit_price, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)) SELECT s.id, s.order_id, s.product_id, s.unit_price, s.quantity_dense_rank, s.quantity_share, s.running_unit_price, s.quantity_share_2, s.quantity_share_3, (SELECT MIN(x.unit_price) FROM order_items x WHERE x.product_id = s.product_id) AS min_order_item_unit_price FROM scored s ORDER BY id NULLS LAST
